-- The Undo Journal: a row-level history of every journaled table, written by triggers.
--
-- Ctrl+Z reverses a Gesture, and the record it reverses from is written here. The recording is
-- done by SQL triggers rather than by the commands, because there are 83 mutating commands and an
-- inverse written per command is a correctness obligation that has to be met 83 times and then
-- again by every command written afterwards. A trigger cannot be forgotten by a command that does
-- not know it exists. See docs/adr/0006-undo-via-a-trigger-written-row-journal.md.
--
-- This migration only *adds* — two tables, one index and three triggers per journaled table. It
-- rewrites no existing table and moves no data, so the RENAME-and-recreate hazard that cost this
-- repository every tag and dependency edge once before does not arise here: with foreign keys on
-- (database::connect's after_connect), PRAGMA legacy_alter_table has no effect and
-- defer_foreign_keys defers violations rather than cascade actions. Nothing below touches a
-- parent row, so nothing cascades.
--
-- Numbering: 0026-0029 are deliberately left free for branches already in flight.

-- The ambient write context the triggers consult, and the only row of it.
--
-- A trigger has no arguments: it can only read what the schema already holds. So the three things
-- a journal entry needs that the row itself cannot supply — which Gesture the write belongs to,
-- who caused it, and whether journalling is suppressed — live in one row that every trigger reads.
--
-- `gesture_id` is NULL when no Gesture is open. Writes then land in the journal ungrouped, and an
-- ungrouped entry is never offered as an undo step: forgetting to open a Gesture makes a change
-- un-undoable, never makes Ctrl+Z reverse the wrong thing.
--
-- `depth` counts nested opens so that a Gesture spanning several commands is not closed by the
-- first of them — the same "join the caller's boundary, never open your own" rule ADR 0004 gives
-- transactions. It is pinned to gesture_id by a CHECK: depth 0 iff no Gesture.
--
-- `source` has no CHECK listing its values on purpose. It is an enum in Rust (undo::WriteSource),
-- so a third source later is a Rust change and not a migration.
--
-- `suppressed` is set by the undo path for the duration of its own transaction, so that applying
-- an inverse writes no journal entries. Because the write that sets it takes SQLite's single
-- writer lock, a transaction that sets it holds that lock until it commits, and no other
-- connection's write can be journalled — or fail to be — under someone else's flag.
CREATE TABLE undo_context (
    id         INTEGER PRIMARY KEY CHECK (id = 1),
    gesture_id TEXT,
    depth      INTEGER NOT NULL DEFAULT 0 CHECK (depth >= 0),
    source     TEXT NOT NULL DEFAULT 'user',
    suppressed INTEGER NOT NULL DEFAULT 0 CHECK (suppressed IN (0, 1)),
    CHECK ((gesture_id IS NULL) = (depth = 0))
);

INSERT INTO undo_context (id) VALUES (1);

-- One entry per journaled row change.
--
-- Row images are JSON so that one schema serves every table: undo speaks in rows, not in the
-- intent behind them. `row_id` is the SQLite rowid rather than a primary key, because six of the
-- journaled tables have a composite primary key and no id column at all.
--
-- `seq` is AUTOINCREMENT: it is the total order undo walks backwards, and plain rowid reuse after
-- a prune could put a later entry before an earlier one.
--
-- The journal is session-scoped — truncated at startup and capped at a depth — so it needs no
-- retention policy and holds nothing across runs.
CREATE TABLE undo_journal (
    seq          INTEGER PRIMARY KEY AUTOINCREMENT,
    gesture_id   TEXT,
    source       TEXT NOT NULL,
    table_name   TEXT NOT NULL,
    row_id       INTEGER NOT NULL,
    operation    TEXT NOT NULL CHECK (operation IN ('insert', 'update', 'delete')),
    before_image TEXT,
    after_image  TEXT,
    written_at   TEXT NOT NULL,
    -- An insert has nothing before it and a delete has nothing after it; an update has both.
    CHECK ((operation = 'insert') = (before_image IS NULL)),
    CHECK ((operation = 'delete') = (after_image IS NULL))
);

CREATE INDEX idx_undo_journal_gesture ON undo_journal (gesture_id, seq);

-- Three triggers per journaled table, generated by scripts/generate-undo-triggers.sh from the
-- schema as of this migration. Every column of the table is named in the image, so a column added
-- later is not journaled until the triggers are regenerated into a new migration — which is what
-- tests/undo_journal.rs checks, column by column, rather than merely counting triggers.
--
-- `scopes` is excluded and is the only domain table that is. A scope row is not authored: it is
-- the calendar, instantiated on demand by ScopeOperator::get_or_create and deduplicated by the
-- three uniqueness indexes over it. Nothing in the codebase ever deletes one. Journalling scopes
-- would mean undo deleting a row that get_or_create will simply recreate — and, worse, deleting
-- one that another item still references, which with foreign keys on fails the undo itself.
-- undo_context and undo_journal are excluded because journalling the journal is a loop.

CREATE TRIGGER undo_journal_block_reasons_insert AFTER INSERT ON block_reasons BEGIN
    INSERT INTO undo_journal (gesture_id, source, table_name, row_id, operation, before_image, after_image, written_at)
    SELECT gesture_id, source, 'block_reasons', new.rowid, 'insert', NULL, json_object('id', new.id, 'owner_type', new.owner_type, 'owner_id', new.owner_id, 'reason', new.reason, 'position', new.position, 'created_at', new.created_at), strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
      FROM undo_context WHERE id = 1 AND suppressed = 0;
END;

CREATE TRIGGER undo_journal_block_reasons_update AFTER UPDATE ON block_reasons BEGIN
    INSERT INTO undo_journal (gesture_id, source, table_name, row_id, operation, before_image, after_image, written_at)
    SELECT gesture_id, source, 'block_reasons', new.rowid, 'update', json_object('id', old.id, 'owner_type', old.owner_type, 'owner_id', old.owner_id, 'reason', old.reason, 'position', old.position, 'created_at', old.created_at), json_object('id', new.id, 'owner_type', new.owner_type, 'owner_id', new.owner_id, 'reason', new.reason, 'position', new.position, 'created_at', new.created_at), strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
      FROM undo_context WHERE id = 1 AND suppressed = 0;
END;

